/* @autogenerated */
package net.civeira.phylax.common.infrastructure.mail;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Optional;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import io.vertx.mutiny.core.Vertx;
import io.vertx.mutiny.ext.mail.MailClient;

@DisplayName("DynamicMailClientCache")
class DynamicMailClientCacheUnitTest {
  private final Vertx vertx = Vertx.vertx();

  @AfterEach
  void tearDown() {
    vertx.closeAndAwait();
  }

  @Test
  @DisplayName("Should reuse the client of the same server and account")
  void shouldReuseClients() {
    DynamicMailClientCache cache = new DynamicMailClientCache(vertx);
    MailConfiguration tls =
        MailConfiguration.builder().smtpHost("smtp").smtpPort(587).smtpLogin("a").build();
    MailConfiguration plain = MailConfiguration.builder().smtpHost("smtp").smtpPort(25)
        .smtpLogin("a").useTtls(false).build();

    MailClient first = cache.clientFor(tls);

    assertSame(first, cache.clientFor(tls));
    assertNotSame(first, cache.clientFor(plain));
    cache.shutdown();
  }

  @Test
  @DisplayName("MailConfiguration should expose defaults and optional sender")
  void configurationShouldExposeDefaults() {
    MailConfiguration config = MailConfiguration.builder().build();

    assertTrue(config.isUseTtls());
    assertEquals(30, config.getWriteTimeout());
    assertEquals(30, config.getConnectionTimeout());
    assertEquals(Optional.empty(), config.getFromName());
    assertFalse(config.getFromEmail().isPresent());
  }
}
